// ❌ OLD ANTI-PATTERN: Returning HTTP 200 OK just to make HTMX swap the error.
// APM tools, logging, and HTTP caches believe the operation succeeded!
app.post('/login', (req, res) => {
  if (!isValid(req.body)) {
    return res.status(200).send('<p class="error">Invalid Credentials</p>');
  }
  res.send('<div>Welcome back!</div>');
});

// ✅ NEW: Return true HTTP 422 status. HX-Retarget tells HTMX to route
// the error partial into #error-box instead of the main form target.
app.post('/login', (req, res) => {
  if (!isValid(req.body)) {
    res.set({
      'HX-Retarget': '#error-box',
      'HX-Reswap': 'innerHTML'
    });
    return res.status(422).send('<p class="alert alert-danger">Invalid credentials</p>');
  }
  res.send('<div>Welcome back!</div>');
});
